package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// use decimal to avoid unused import error
var _ = decimal.NewFromInt(0)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                    // PIC X len=1 = "N"
var WsLabel string = strings.Repeat(" ", 20) // PIC X(20) len=20 = SPACES
var WsACount int64 = 0                        // PIC 99 len=2 = 0
var WsTotalA int64 = 0                        // PIC 999 len=3 = 0
var WsCount int64 = 0                         // PIC 999 len=3 = 0

var partRec PartRec

var partFile *os.File
var scanner *bufio.Scanner

func main() {
	MAIN_PARA()
}

func MAIN_PARA() {
	OPEN_INPUT_PART_FILE()
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	CLOSE_PART_FILE()
	SUMMARY_PARA()
}

func OPEN_INPUT_PART_FILE() {
	f, err := os.Open("input.dat")
	if err != nil {
		// file not found -> treat as EOF, create empty scanner
		partFile = nil
		scanner = bufio.NewScanner(strings.NewReader(""))
		WsEofFlag = "N"
		return
	}
	partFile = f
	scanner = bufio.NewScanner(f)
	// increase buffer for long lines (though record is 15)
	const maxCapacity = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCapacity)
}

func CLOSE_PART_FILE() {
	if partFile != nil {
		partFile.Close()
	}
}

func READ_PARA() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		// LINE SEQUENTIAL pads short records with spaces
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		partRec.LbPart = line[0:8]
		partRec.LbRegion = line[8:11]
		s := line[11:15]
		t := strings.TrimSpace(s)
		if t == "" {
			partRec.LbSerial = 0
		} else {
			// t should be digits; parse
			v, err := strconv.ParseInt(t, 10, 64)
			if err != nil {
				// if contains spaces or non-digits, try to filter digits
				// but for strictness, treat as 0
				v = 0
				// attempt digit extraction
				filtered := ""
				for _, ch := range t {
					if ch >= '0' && ch <= '9' {
						filtered += string(ch)
					}
				}
				if filtered != "" {
					if pv, e2 := strconv.ParseInt(filtered, 10, 64); e2 == nil {
						v = pv
					}
				}
			}
			// store into PIC 9(4) -> keep low-order 4 digits
			v = v % 10000
			if v < 0 {
				v += 10000
			}
			partRec.LbSerial = v
		}
		WsEofFlag = "N"
	} else {
		WsEofFlag = "Y"
	}
}

func PROCESS_PARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	// count occurrences of "A" in LbPart (8 bytes)
	WsACount = int64(strings.Count(partRec.LbPart, "A"))
	// truncate to PIC 99 (low-order 2 digits) – not needed as max 8, but obey spec
	WsACount = WsACount % 100

	// STRING LB-REGION DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-PART DELIMITED BY SPACE
	//        "-" DELIMITED BY SIZE
	//        LB-SERIAL DELIMITED BY SIZE
	//   INTO WS-LABEL
	// WS-LABEL is initially 20 spaces
	buf := make([]byte, 20)
	for i := range buf {
		buf[i] = ' '
	}
	pos := 0
	appendStr := func(s string) {
		for i := 0; i < len(s); i++ {
			if pos < 20 {
				buf[pos] = s[i]
				pos++
			} else {
				break
			}
		}
	}
	// LB-REGION DELIMITED BY SPACE
	regionPart := partRec.LbRegion
	if idx := strings.Index(regionPart, " "); idx != -1 {
		regionPart = regionPart[:idx]
	}
	appendStr(regionPart)
	appendStr("-")
	partPart := partRec.LbPart
	if idx := strings.Index(partPart, " "); idx != -1 {
		partPart = partPart[:idx]
	}
	appendStr(partPart)
	appendStr("-")
	serialStr := fmt.Sprintf("%04d", partRec.LbSerial)
	appendStr(serialStr)

	WsLabel = string(buf)
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = WsTotalA + WsACount
	WsTotalA = WsTotalA % 1000 // PIC 999 truncation

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	WsCount = WsCount % 1000 // PIC 999 truncation

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL is X(20) -> exactly 20 chars
	// WS-A-COUNT is 99 -> zero-padded 2 digits
	aCountStr := fmt.Sprintf("%02d", WsACount)
	line := WsLabel + " A=" + aCountStr + "\n"
	_, _ = os.Stdout.WriteString(line)

	// PERFORM READ-PARA
	READ_PARA()
}

func SUMMARY_PARA() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A.
	countStr := fmt.Sprintf("%03d", WsCount)
	totalStr := fmt.Sprintf("%03d", WsTotalA)
	line := "LABELS: " + countStr + " A-TOTAL: " + totalStr + "\n"
	_, _ = os.Stdout.WriteString(line)
}
